#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;

long long modPow(long long base, int exp, long long m) {
    long long res = 1;
    base %= m;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % m;
        base = (base * base) % m;
        exp >>= 1;
    }
    return res;
}

long long modInverse(long long a, long long m) {
    return modPow(a, m - 2, m);
}

long long nCr(int n, int r, const std::vector<long long>& fact, const std::vector<long long>& invFact) {
    return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long k;
    cin >> n >> k;

    if (k >= n) {
        cout << 0 << "\n";
        return 0;
    }

    std::vector<long long> factorials(n + 1);
    std::vector<long long> invFactorials(n + 1);
    factorials[0] = 1;
    for (int i = 1; i <= n; i++) {
        factorials[i] = (factorials[i - 1] * i) % MOD;
    }
    invFactorials[n] = modInverse(factorials[n], MOD);
    for (int i = n - 1; i >= 1; i--) {
        invFactorials[i] = ((i + 1) * invFactorials[i + 1]) % MOD;
    }

    if (k == 0) {
        cout << factorials[n] << "\n";
        return 0;
    }

    int r = n - (int)k;
    long long sum = 0;
    int sign = 1;
    for (int i = 0; i < r; i++) {
        long long comb = nCr(n, i, factorials, invFactorials);
        long long val = modPow(r - i, n, MOD);
        sum = (sum + sign * comb % MOD * val % MOD) % MOD;
        sign *= -1;
    }
    long long answer = (2 * nCr(n, r, factorials, invFactorials) % MOD * sum) % MOD;
    cout << answer << "\n";

    return 0;
}
